import java.io.*;
import java.net.*;
import java.nio.*;
import java.nio.charset.*;
import java.security.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;
import java.util.Base64;

public class SecureWebSocketServer {
    private static final int PORT = 8443;
    private static final AtomicBoolean shutdownRequested = new AtomicBoolean(false);
    private static final ConcurrentHashMap<String, Long> sessionRegistry = new ConcurrentHashMap<>();
    private static volatile long nativeContextPtr = 0;
    private static final ReadWriteLock nativeCtxLock = new ReentrantReadWriteLock();

    // Handshake safety limits
    private static final int MAX_HANDSHAKE_HEADERS = 100;
    private static final int MAX_HANDSHAKE_LINE_LENGTH = 8192;

    // JNI native methods for TLS acceleration
    private static native long nativeInitContext(byte[] configData);
    private static native int nativeProcessFrame(long ctxPtr, byte[] input, byte[] output, int outputLen);
    private static native void nativeDestroyContext(long ctxPtr);

    static {
        System.loadLibrary("wsaccel");
    }

    private final ExecutorService workerPool;
    private final ScheduledExecutorService scheduler;
    private ServerSocket serverSocket;

    public SecureWebSocketServer() {
        this.workerPool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.scheduler = Executors.newScheduledThreadPool(1);
    }

    public void start() throws IOException {
        byte[] config = loadConfiguration();
        nativeContextPtr = nativeInitContext(config);

        serverSocket = new ServerSocket(PORT);
        scheduler.scheduleAtFixedRate(this::cleanupStaleSessions, 30, 30, TimeUnit.SECONDS);

        Runtime.getRuntime().addShutdownHook(new Thread(this::gracefulShutdown));

        while (!shutdownRequested.get()) {
            try {
                Socket client = serverSocket.accept();
                workerPool.submit(() -> handleConnection(client));
            } catch (SocketException e) {
                if (!shutdownRequested.get()) throw e;
            }
        }
    }

    private void handleConnection(Socket client) {
        String sessionId = generateSessionId();
        sessionRegistry.put(sessionId, System.currentTimeMillis());

        try (InputStream in = client.getInputStream();
             OutputStream out = client.getOutputStream()) {

            if (!performWebSocketHandshake(in, out)) return;

            byte[] frameBuffer = new byte[65536];
            byte[] outputBuffer = new byte[65536];

            while (!shutdownRequested.get() && !client.isClosed()) {
                int bytesRead = readWebSocketFrame(in, frameBuffer);
                if (bytesRead <= 0) break;

                // Process frame through native TLS accelerator with proper locking
                nativeCtxLock.readLock().lock();
                try {
                    long currentCtx = nativeContextPtr;
                    if (currentCtx == 0) break;

                    int processed = nativeProcessFrame(currentCtx, frameBuffer, outputBuffer, bytesRead);
                    if (processed > 0) {
                        sendWebSocketFrame(out, outputBuffer, processed);
                    }
                } finally {
                    nativeCtxLock.readLock().unlock();
                }

                sessionRegistry.put(sessionId, System.currentTimeMillis());
            }
        } catch (IOException e) {
            // Connection handling error
        } finally {
            sessionRegistry.remove(sessionId);
            try { client.close(); } catch (IOException ignored) {}
        }
    }

    private void gracefulShutdown() {
        shutdownRequested.set(true);

        // Phase 1: Stop accepting new connections
        try { serverSocket.close(); } catch (IOException ignored) {}

        // Phase 2: Wait for active connections to drain completely
        workerPool.shutdown();
        try {
            if (!workerPool.awaitTermination(30, TimeUnit.SECONDS)) {
                workerPool.shutdownNow();
                workerPool.awaitTermination(5, TimeUnit.SECONDS);
            }
        } catch (InterruptedException e) {
            workerPool.shutdownNow();
            Thread.currentThread().interrupt();
        }

        // Phase 3: Destroy native context under write lock
        nativeCtxLock.writeLock().lock();
        try {
            long ctx = nativeContextPtr;
            nativeContextPtr = 0;
            if (ctx != 0) {
                nativeDestroyContext(ctx);
            }
        } finally {
            nativeCtxLock.writeLock().unlock();
        }

        scheduler.shutdownNow();
    }

    private boolean performWebSocketHandshake(InputStream in, OutputStream out) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
        String line;
        String wsKey = null;

        int headerCount = 0;
        while ((line = reader.readLine()) != null && !line.isEmpty()) {
            // Bound the number and size of headers to prevent memory exhaustion DoS
            if (++headerCount > MAX_HANDSHAKE_HEADERS || line.length() > MAX_HANDSHAKE_LINE_LENGTH) {
                return false;
            }
            if (line.startsWith("Sec-WebSocket-Key:")) {
                wsKey = line.substring(18).trim();
            }
        }

        if (wsKey == null) return false;

        String acceptKey = computeAcceptKey(wsKey);
        String response = "HTTP/1.1 101 Switching Protocols\r\n" +
                         "Upgrade: websocket\r\n" +
                         "Connection: Upgrade\r\n" +
                         "Sec-WebSocket-Accept: " + acceptKey + "\r\n\r\n";
        out.write(response.getBytes(StandardCharsets.UTF_8));
        out.flush();
        return true;
    }

    private String computeAcceptKey(String wsKey) {
        try {
            String combined = wsKey + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
            MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
            byte[] hash = sha1.digest(combined.getBytes(StandardCharsets.UTF_8));
            return Base64.getEncoder().encodeToString(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private int readWebSocketFrame(InputStream in, byte[] buffer) throws IOException {
        int firstByte = in.read();
        if (firstByte == -1) return -1;

        int secondByte = in.read();
        if (secondByte == -1) return -1;

        boolean masked = (secondByte & 0x80) != 0;
        int payloadLen = secondByte & 0x7F;

        if (payloadLen == 126) {
            int b1 = in.read();
            int b2 = in.read();
            if (b1 == -1 || b2 == -1) return -1;
            payloadLen = (b1 << 8) | b2;
        } else if (payloadLen == 127) {
            // Read 8-byte extended length, checking for EOF on each byte
            long extLen = 0;
            for (int i = 0; i < 8; i++) {
                int b = in.read();
                if (b == -1) return -1;
                extLen = (extLen << 8) | b;
            }
            if (extLen < 0 || extLen > buffer.length) return -1;
            payloadLen = (int) extLen;
        }

        if (payloadLen > buffer.length || payloadLen < 0) return -1;

        byte[] maskKey = new byte[4];
        if (masked) {
            // Ensure all 4 mask bytes are fully read
            int maskRead = 0;
            while (maskRead < 4) {
                int r = in.read(maskKey, maskRead, 4 - maskRead);
                if (r == -1) return -1;
                maskRead += r;
            }
        }

        int totalRead = 0;
        while (totalRead < payloadLen) {
            int read = in.read(buffer, totalRead, payloadLen - totalRead);
            if (read == -1) return -1;
            totalRead += read;
        }

        if (masked) {
            for (int i = 0; i < payloadLen; i++) {
                buffer[i] ^= maskKey[i % 4];
            }
        }

        return payloadLen;
    }

    private void sendWebSocketFrame(OutputStream out, byte[] data, int length) throws IOException {
        out.write(0x81); // FIN + text frame
        if (length < 126) {
            out.write(length);
        } else if (length < 65536) {
            out.write(126);
            out.write((length >> 8) & 0xFF);
            out.write(length & 0xFF);
        }
        out.write(data, 0, length);
        out.flush();
    }

    private void cleanupStaleSessions() {
        long cutoff = System.currentTimeMillis() - 300000;
        sessionRegistry.entrySet().removeIf(e -> e.getValue() < cutoff);
    }

    private String generateSessionId() {
        byte[] bytes = new byte[16];
        new SecureRandom().nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    private byte[] loadConfiguration() {
        // Load from secure configuration store
        return new byte[]{0x01, 0x00, 0x10, 0x00};
    }

    public static void main(String[] args) throws IOException {
        new SecureWebSocketServer().start();
    }
}
